/**
 * The page's fonts (D-083, S3), inside the binary so the page stays offline and CDN-free: Inter for Latin at 400,
 * 500 and 600 (the shared design system's face, spec §2) and IBM Plex Sans Thai for Thai at 400 and 600, which Inter
 * has no glyphs for, so Thai falls to Plex glyph by glyph. The Thai rules carry `size-adjust` so a Thai letter is as
 * big as a Latin one (the token `--thai-size-adjust`, 102.6%: Inter's x-height over Plex Sans Thai's, as mind-app
 * measured it). Electrolize, the old display face, and Plex's two Latin subsets are gone: Inter draws every Latin glyph.
 * Both SIL Open Font License 1.1 — the licences are beside this file in fonts/. The Inter files are mind-platform's
 * `src/ui/fonts/inter-*.woff2` (the 24pt cuts of Inter 4.001 from mind-app, whole files, converted to woff2 and changed
 * in nothing else); the Thai files are @fontsource v5 subsets, as before.
 * Served at /fonts/<name>.woff2 by the web server.
 */

export const FONT_FILES: Readonly<Record<string, string>> = {
  "inter-400": "",
  "inter-500": "",
  "inter-600": "",
  "plex-thai-thai-400": "",
  "plex-thai-thai-600": "",
};

/** The bytes of one font, or `undefined` for a name that is not one. */
export function fontBytes(name: string): Uint8Array | undefined {
  const b64 = Object.hasOwn(FONT_FILES, name) ? FONT_FILES[name] : undefined;
  return b64 === undefined ? undefined : Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

const THAI = "U+02D7,U+0303,U+0331,U+0E01-0E5B,U+200C-200D,U+25CC";

/** How much bigger a Thai letter is drawn than its font makes it (`--thai-size-adjust` in the tokens). */
export const THAI_SIZE_ADJUST = "102.6%";

const face = (family: string, file: string, weight: number, range: string | null, sizeAdjust: string | null) => {
  const descriptors = [
    `font-family:"${family}"`,
    "font-style:normal",
    `font-weight:${weight}`,
    "font-display:swap",
    `src:url(/fonts/${file}.woff2) format("woff2")`,
    ...(range === null ? [] : [`unicode-range:${range}`]),
    ...(sizeAdjust === null ? [] : [`size-adjust:${sizeAdjust}`]),
  ];
  return `@font-face{${descriptors.join(";")}}`;
};

export const FONT_CSS = [
  face("Inter", "inter-400", 400, null, null),
  face("Inter", "inter-500", 500, null, null),
  face("Inter", "inter-600", 600, null, null),
  face("IBM Plex Sans Thai", "plex-thai-thai-400", 400, THAI, THAI_SIZE_ADJUST),
  face("IBM Plex Sans Thai", "plex-thai-thai-600", 600, THAI, THAI_SIZE_ADJUST),
].join("\n");

/** The spec's stack (`--font-sans`): Latin from Inter, Thai from Plex, then the system's. */
export const FONT_STACK = `"Inter", "IBM Plex Sans Thai", system-ui, -apple-system, "Segoe UI", sans-serif`;
